<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$id=(int)($_GET['id']??$_POST['id']??0);$row=['client_name'=>'','company'=>'','position'=>'','testimonial'=>'','image'=>'','is_published'=>1];if($id){$s=db()->prepare('SELECT * FROM testimonials WHERE id=?');$s->execute([$id]);$row=$s->fetch()?:$row;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['client_name','company','position','testimonial','image'] as $k)$row[$k]=trim((string)($_POST[$k]??''));$row['is_published']=isset($_POST['is_published'])?1:0;if($row['client_name']===''||$row['testimonial']==='')$error='Client name and testimonial are required.';if(!$error){if($id)db()->prepare('UPDATE testimonials SET client_name=?,company=?,position=?,testimonial=?,image=?,is_published=? WHERE id=?')->execute([$row['client_name'],$row['company'],$row['position'],$row['testimonial'],$row['image'],$row['is_published'],$id]);else db()->prepare('INSERT INTO testimonials(client_name,company,position,testimonial,image,is_published) VALUES(?,?,?,?,?,?)')->execute([$row['client_name'],$row['company'],$row['position'],$row['testimonial'],$row['image'],$row['is_published']]);header('Location: testimonials.php');exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Testimonial</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:800px"><div class="d-flex justify-content-between mb-4"><h1><?= $id?'Edit':'Add' ?> Testimonial</h1><a class="btn btn-outline-secondary" href="testimonials.php">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Client Name</label><input name="client_name" class="form-control" value="<?=htmlspecialchars($row['client_name'])?>" required></div><div class="col-md-6"><label class="form-label">Company</label><input name="company" class="form-control" value="<?=htmlspecialchars($row['company'])?>"></div><div class="col-md-6"><label class="form-label">Position</label><input name="position" class="form-control" value="<?=htmlspecialchars($row['position'])?>"></div><div class="col-md-6"><label class="form-label">Image</label><input name="image" class="form-control" value="<?=htmlspecialchars($row['image'])?>"></div><div class="col-12"><label class="form-label">Testimonial</label><textarea name="testimonial" class="form-control" rows="6" required><?=htmlspecialchars($row['testimonial'])?></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_published" id="published" <?=((int)$row['is_published']?'checked':'')?>><label class="form-check-label" for="published">Published</label></div></div><div class="col-12"><button class="btn btn-primary">Save Testimonial</button></div></div></form></main></body></html>